"""de — virtues_c."""

T = {
"virtues_051": ("Was rät Luqman seinem Sohn bezüglich der Stimme?", ["Die Stimme zu senken: die widerwärtigste ist die des Esels", "Sehr laut zu sprechen", "Nie zu sprechen", "Beim Gehen zu singen"], "«Und halte Maß in deinem Gang und senke deine Stimme: die widerwärtigste der Stimmen ist die des Esels»."),
"virtues_052": ("Welche drei Ermahnungen gibt Luqman seinem Sohn, bevor er von Geduld spricht?", ["Das Gebet zu verrichten, das Rechte zu gebieten, das Verwerfliche zu verbieten", "Reisen, handeln, schreiben", "Wenig essen, wenig schlafen, wenig reden", "Bauen, pflanzen, ernten"], "«O mein Sohn, verrichte das Gebet, gebiete das Rechte, verbiete das Verwerfliche und ertrage standhaft, was dich trifft»."),
"virtues_053": ("Welche drei Eigenschaften schreibt der Koran den Gottesfürchtigen in der Sure Al 'Imran zu?", ["In Fülle und Not zu spenden, den Zorn zu zügeln, den Menschen zu verzeihen", "Fasten, Nachtwache, Schweigen", "Bauen, pflanzen, geben", "Reisen, lernen, lehren"], "«Diejenigen, die in Fülle und in Not spenden, den Zorn zurückhalten und den Menschen verzeihen: Allah liebt die Gutes Tuenden»."),
"virtues_054": ("Was hält der Koran für besser als eine Spende, der eine Kränkung folgt?", ["Ein freundliches Wort und Vergebung", "Eine größere Gabe", "Völliges Schweigen", "Einen Eid"], "«Ein freundliches Wort und Vergebung sind besser als eine Spende, der Kränkung folgt»."),
"virtues_055": ("Was sagt der Koran über die im Verborgenen gegebene Spende?", ["Sie ist besser für den Gebenden", "Sie zählt nicht", "Sie muss angekündigt werden", "Sie ist verboten"], "«Wenn ihr die Almosen offen zeigt, so ist es trefflich; wenn ihr sie aber verbergt und den Armen gebt, so ist es besser für euch»."),
"virtues_056": ("Wovon verbietet der Koran zu spenden?", ["Von dem, was man selbst nur mit geschlossenen Augen annähme", "Von dem Neuen", "Von dem, was man liebt", "Von einem Erbe"], "«Und sucht nicht das Schlechte davon aus, um davon auszugeben, während ihr es selbst nur nähmet, wenn ihr die Augen zudrücktet»."),
"virtues_057": ("Wann erreicht man die wahre Frömmigkeit, laut Sure Al 'Imran?", ["Indem man von dem gibt, was man liebt", "Indem man den Überschuss gibt", "Indem man öffentlich gibt", "Indem man alles behält"], "«Ihr werdet die Frömmigkeit nicht erreichen, bevor ihr nicht von dem gebt, was ihr liebt»."),
"virtues_058": ("Welches Bild gebraucht der Koran für das Maßhalten beim Ausgeben?", ["Die Hand weder an den Hals gefesselt halten noch ganz ausstrecken", "Die Tür schließen", "Langsam gehen", "Zweimal zählen"], "«Und lass deine Hand nicht an deinen Hals gefesselt sein, strecke sie aber auch nicht ganz aus, sonst sitzt du getadelt und mittellos da»."),
"virtues_059": ("Wie beschreibt der Koran das Ausgeben der «Diener des Allerbarmers»?", ["Weder verschwenderisch noch geizig, sondern in der Mitte", "Immer maßlos freigebig", "Immer sparsam", "Ohne je zu geben"], "«Und diejenigen, die, wenn sie ausgeben, weder maßlos noch knauserig sind, sondern die Mitte dazwischen halten»."),
"virtues_060": ("Was gebietet der Koran vor dem Betreten eines fremden Hauses?", ["Um Erlaubnis zu bitten und seine Bewohner zu grüßen", "Dreimal zu klopfen und einzutreten", "Direkt einzutreten", "Von weitem zu rufen"], "«Betretet nicht andere Häuser als eure eigenen, bevor ihr um Erlaubnis gebeten und ihre Bewohner begrüßt habt»."),
"virtues_061": ("Was ist zu tun, wenn man aufgefordert wird zurückzukehren, laut Sure An-Nur?", ["Umkehren: das ist reiner für einen", "Beharren", "An der Tür warten", "Trotzdem eintreten"], "«Und wenn zu euch gesagt wird: “Kehrt um”, dann kehrt um: das ist reiner für euch»."),
"virtues_062": ("Was gebietet der Koran, wenn ein Unzuverlässiger eine Nachricht bringt?", ["Sie zu prüfen, damit nicht aus Unwissenheit Menschen Schaden nehmen", "Sie sofort zu verbreiten", "Sie aufzuschreiben", "Sie stets zu ignorieren"], "«Wenn ein Frevler zu euch mit einer Nachricht kommt, dann schafft Klarheit, damit ihr nicht aus Unwissenheit Leuten Schaden zufügt und dann bereut»."),
"virtues_063": ("Welches Verhalten verbietet die Sure Al-Hujurat neben der üblen Nachrede?", ["Das Ausspähen und übermäßiges Misstrauen", "Allein zu reisen", "Leise zu sprechen", "Briefe zu schreiben"], "«O die ihr glaubt! Meidet viel Mutmaßung; gewiss, manche Mutmaßung ist Sünde. Und spioniert nicht und führt nicht üble Nachrede übereinander»."),
"virtues_064": ("Was gebietet der Koran, wenn zwei Gruppen von Gläubigen einander bekämpfen?", ["Sie gerecht zu versöhnen", "Für eine Seite Partei zu ergreifen", "Sie zu ignorieren", "Sie nur mit Gewalt zu trennen"], "«Und wenn zwei Gruppen von Gläubigen einander bekämpfen, dann stiftet Frieden zwischen ihnen… und handelt gerecht: Allah liebt die Gerechten»."),
"virtues_065": ("Was verbietet der Koran ausdrücklich, selbst gegenüber einem verhassten Volk?", ["Dass Hass von der Gerechtigkeit abbringt", "Den Handel", "Das Wort", "Die Nachbarschaft"], "«Und der Hass gegen ein Volk soll euch nicht dazu verleiten, ungerecht zu sein. Seid gerecht: das ist der Gottesfurcht näher»."),
"virtues_066": ("Gegen wen verlangt der Koran nötigenfalls gerechtes Zeugnis?", ["Gegen sich selbst, die Eltern und die Verwandten", "Nur gegen Fremde", "Nur gegen Reiche", "Nur gegen Arme"], "«Seid Wahrer der Gerechtigkeit, Zeugen für Allah, auch wenn es gegen euch selbst oder gegen die Eltern und nächsten Verwandten wäre»."),
"virtues_067": ("Was gebietet der Koran ihren Berechtigten zurückzugeben?", ["Die anvertrauten Güter (Amanat)", "Die Briefe", "Die Ernten", "Die Erzählungen"], "«Allah befiehlt euch, anvertraute Güter ihren Eigentümern zurückzugeben, und wenn ihr zwischen den Menschen richtet, gerecht zu richten»."),
"virtues_068": ("Welche Menschen zählt Vers 4:36 nach den Eltern für gute Behandlung auf?", ["Die Verwandten, die Waisen, die Armen, den nahen und den fernen Nachbarn, den Gefährten, den Reisenden und den Diener", "Die Könige und Anführer", "Die Kaufleute", "Nur die Gelehrten"], "«Und dient Allah und gesellt Ihm nichts bei. Und zu den Eltern sollt ihr gütig sein, und zu den Verwandten, den Waisen, den Armen, dem verwandten Nachbarn, dem fremden Nachbarn, dem Gefährten zur Seite, dem Reisenden und denen, die eure rechte Hand besitzt»."),
"virtues_069": ("Was gebietet der Koran gegenüber einem Schuldner in Bedrängnis?", ["Ihm Aufschub bis zur Erleichterung zu gewähren", "Ihn zu verfolgen", "Die Schuld zu verdoppeln", "Ihn zu vertreiben"], "«Und wenn er in Schwierigkeiten ist, dann sei ihm Aufschub gewährt bis zu einer Zeit der Erleichterung; aber es ist besser für euch, die Schuld zu erlassen»."),
"virtues_070": ("Was gebietet der längste Vers des Korans bezüglich einer befristeten Schuld?", ["Sie schriftlich festzuhalten", "Sie geheim zu halten", "Sie zu vergessen", "Sie mündlich weiterzugeben"], "«O die ihr glaubt! Wenn ihr eine Schuld für eine bestimmte Frist eingeht, dann schreibt sie nieder»."),
"virtues_071": ("Was verbietet der Koran bezüglich des Besitzes anderer?", ["Ihn zu Unrecht zu verzehren oder damit Richter zu bestechen", "Ihn zu zählen", "Ihn zu verkaufen", "Ihn zu bewahren"], "«Und verzehrt nicht zu Unrecht euren Besitz untereinander und bestecht nicht damit die Richter, um einen Teil des Besitzes der Menschen in sündhafter Weise zu verzehren»."),
"virtues_072": ("Was gebietet der Koran bezüglich des Besitzes der Waisen?", ["Ihn ihnen zu geben, ohne Gutes gegen Schlechtes zu tauschen", "Ihn aufzuteilen", "Ihn zu verkaufen", "Ihn auf Lebenszeit zu behalten"], "«Und gebt den Waisen ihren Besitz; und tauscht nicht Schlechtes gegen Gutes ein und verzehrt nicht ihren Besitz zusammen mit eurem Besitz»."),
"virtues_073": ("Wie gebietet der Koran zu messen und zu wiegen?", ["Volles Maß zu geben und mit gerechter Waage zu wiegen", "Zu eigenen Gunsten aufzurunden", "Nach Augenmaß zu wiegen", "Zweimal zu messen"], "«Und gebt volles Maß, wenn ihr messt, und wägt mit der richtigen Waage: das ist besser und ein schöneres Ergebnis»."),
"virtues_074": ("Wovon verbietet der Koran, ihm ohne Wissen zu folgen?", ["Dem, wovon man kein Wissen hat: Gehör, Auge und Herz werden dafür befragt", "Dem kürzesten Weg", "Den Karawanen", "Dem Schweigen"], "«Und folge nicht dem, wovon du kein Wissen hast: Gehör, Augenlicht und Herz, nach all diesem wird gefragt werden»."),
"virtues_075": ("Welches Bild gibt der Koran vom Hochmut im Gang?", ["Man kann die Erde nicht spalten noch die Berge an Höhe erreichen", "Man kommt schneller voran", "Man ermüdet weniger", "Man wird geachtet"], "«Und gehe nicht übermütig auf der Erde einher: du wirst weder die Erde aufreißen noch die Berge an Höhe erreichen»."),
"virtues_076": ("Welche Eigenschaft der Rede gebietet der Koran und verspricht, dass die Werke in Ordnung gebracht werden?", ["Eine treffende, aufrichtige Rede (qawl sadid)", "Eine kurze Rede", "Eine gelehrte Rede", "Eine schriftliche Rede"], "«O die ihr glaubt! Fürchtet Allah und sagt treffende Worte: Er bringt eure Werke in Ordnung und vergibt euch eure Sünden»."),
"virtues_077": ("Welche Art von Rede wurde im Koran selbst vor einem Tyrannen geboten?", ["Eine sanfte Rede", "Eine drohende Rede", "Eine spöttische Rede", "Das Schweigen"], "«Und sprecht zu ihm mit sanften Worten: vielleicht lässt er sich ermahnen oder fürchtet sich»."),
"virtues_078": ("Von wem sagt der Koran, er habe die schönste Rede?", ["Von dem, der zu Allah ruft, rechtschaffen handelt und sagt: ich gehöre zu den Muslimen", "Vom Dichter", "Vom Redner", "Vom Richter"], "«Und wer spricht bessere Worte als jemand, der zu Allah ruft, rechtschaffen handelt und sagt: Gewiss, ich gehöre zu den Muslimen?»"),
"virtues_079": ("Wovon wenden sich die erfolgreichen Gläubigen laut Al-Mu'minun ab?", ["Vom unnützen Gerede (al-laghw)", "Von der Arbeit", "Von den Reisen", "Von den Mahlzeiten"], "«…und diejenigen, die sich vom unnützen Gerede abwenden»."),
"virtues_080": ("Welche zwei Anvertrauungen wahren die erfolgreichen Gläubigen laut Al-Mu'minun?", ["Die ihnen anvertrauten Güter und ihre Verpflichtungen", "Fasten und Nachtwache", "Reise und Handel", "Schrift und Lesung"], "«Und diejenigen, die auf das ihnen Anvertraute und ihre Verpflichtung achtgeben»."),
"virtues_081": ("Was sagt der Koran über den, der verzeiht und versöhnt, obwohl er Böses vergelten könnte?", ["Sein Lohn obliegt Allah", "Er verliert sein Recht", "Er wird getadelt", "Er muss schweigen"], "«Die Vergeltung für eine böse Tat ist eine ebensolche böse Tat. Wer aber verzeiht und Besserung bringt, dessen Lohn obliegt Allah»."),
"virtues_082": ("Welches Argument gibt der Koran, um dem zu verzeihen, der einem Unrecht tat?", ["«Liebt ihr es nicht, dass Allah euch vergibt?»", "«Ihr werdet mit Geld entschädigt»", "«Es macht euch mächtig»", "«Es erspart euch einen Prozess»"], "«Sie sollen verzeihen und nachsichtig sein. Liebt ihr es nicht, dass Allah euch vergibt? Und Allah ist Allvergebend und Barmherzig»."),
"virtues_083": ("Welche drei Anweisungen vereint Vers 7:199?", ["Nachsicht üben, das Rechte gebieten und sich von den Toren abwenden", "Kämpfen, fliehen, schweigen", "Essen, trinken, schlafen", "Zählen, schreiben, lesen"], "«Nimm, was leicht zu erlangen ist, gebiete das Rechte und wende dich von den Toren ab»."),
"virtues_084": ("Welche Haltung empfiehlt der Koran angesichts verletzender Worte und der Prüfung?", ["Geduld und Gottesfurcht: das gehört zu den Dingen, die Entschlossenheit erfordern", "Die sofortige Erwiderung", "Den endgültigen Rückzug", "Verächtliches Schweigen"], "«Ihr werdet von denen, denen vor euch die Schrift gegeben wurde, viel Kränkendes hören. Wenn ihr aber standhaft und gottesfürchtig seid, so gehört das zu den Dingen, die Entschlossenheit erfordern»."),
"virtues_085": ("Wie kennzeichnet der Koran Geduld und Vergebung?", ["Sie gehören zu den Dingen, die Entschlossenheit erfordern", "Sie sind Schwäche", "Sie sind freiwillig", "Sie sind nur für Gelehrte"], "«Und wahrlich, wenn einer standhaft ist und vergibt, so gehört das zu den Dingen, die Entschlossenheit erfordern»."),
"virtues_086": ("Für wen ist das Gebet laut Koran keine schwere Last?", ["Für die Demütigen vor Allah (al-khaschi'in)", "Für die Reichen", "Für die Gelehrten", "Für die Reisenden"], "«Sucht Hilfe in der Geduld und im Gebet: das ist wahrlich schwer, außer für die Demütigen»."),
"virtues_087": ("Woran erinnert der Koran bezüglich dessen, was man verabscheut oder liebt?", ["Vielleicht verabscheut ihr etwas, das gut für euch ist, und liebt etwas, das schlecht für euch ist", "Was du liebst, ist immer gut", "Was du verabscheust, ist immer schlecht", "Man weiß immer, was gut ist"], "«Vielleicht ist euch etwas zuwider, während es gut für euch ist; und vielleicht liebt ihr etwas, während es schlecht für euch ist. Allah weiß, ihr aber wisst nicht»."),
"virtues_088": ("Was verspricht der Koran dem, der Allah fürchtet, an Ausweg und Versorgung?", ["Einen Ausweg und Versorgung, von wo er nicht damit rechnet", "Sofortigen Reichtum", "Eine lange Reise", "Ein öffentliches Amt"], "«Und wer Allah fürchtet, dem schafft Er einen Ausweg und versorgt ihn, von wo er nicht damit rechnet»."),
"virtues_089": ("Welche Dankbarkeit gebietet der Koran im selben Atemzug wie die gegenüber Allah?", ["Die Dankbarkeit gegenüber den Eltern", "Gegenüber dem Herrn", "Gegenüber dem Nachbarn", "Gegenüber dem König"], "«Sei Mir und deinen Eltern dankbar: zu Mir ist die Rückkehr»."),
"virtues_090": ("Welche Grenze setzt der Koran dem Gehorsam gegenüber den Eltern?", ["Ihnen nicht zu gehorchen, wenn sie befehlen, Allah etwas beizugesellen", "Ihnen nie zu gehorchen", "Ihnen in allem zu gehorchen", "Ihnen nur auf Reisen zu gehorchen"], "«Wenn sie sich aber darum bemühen, dass du Mir das beigesellst, wovon du kein Wissen hast, dann gehorche ihnen nicht; und begleite sie in dieser Welt in rechtlicher Weise»."),
"virtues_091": ("Welches Bittgebet lehrt der Koran bezüglich der Eltern und der Nachkommenschaft?", ["Für die Gnade zu danken, Gutes zu tun und dass die Nachkommenschaft rechtschaffen werde", "Um Reichtum zu bitten", "Um eine lange Reise zu bitten", "Um ein Amt zu bitten"], "«Mein Herr, gib mir ein, für Deine Gunst zu danken, die Du mir und meinen Eltern erwiesen hast, und rechtschaffen zu handeln; und mache mir meine Nachkommenschaft rechtschaffen»."),
"virtues_092": ("Worum bitten «die Diener des Allerbarmers» bezüglich ihrer Familie?", ["Dass sie Freude der Augen sei und dass sie ein Vorbild für die Gottesfürchtigen seien", "Dass sie reich sei", "Dass sie zahlreich sei", "Dass sie reise"], "«Unser Herr, schenke uns an unseren Gattinnen und unseren Nachkommen Freude der Augen, und mache uns zu einem Vorbild für die Gottesfürchtigen»."),
"virtues_093": ("Wie verhalten sich «die Diener des Allerbarmers» gegenüber dem Unnützen?", ["Sie gehen würdevoll vorüber", "Sie bleiben stehen, um zuzuhören", "Sie antworten scharf", "Sie schreiben es auf"], "«Und diejenigen, die keine Falschaussage machen und, wenn sie an unnützem Gerede vorbeikommen, würdevoll vorbeigehen»."),
"virtues_094": ("Was gebietet der Koran in einer Versammlung, wenn um Platz gebeten wird?", ["Platz zu machen: Allah wird euch Platz machen", "Gedrängt zu bleiben", "Hinauszugehen", "Zu schweigen"], "«O die ihr glaubt! Wenn zu euch gesagt wird: “Macht Platz in den Versammlungen”, dann macht Platz: Allah wird euch Platz machen»."),
"virtues_095": ("Mit wem gebietet der Koran in der Sure At-Tawba zu sein?", ["Mit den Wahrhaftigen", "Mit den Mächtigen", "Mit den Reichen", "Mit den Reisenden"], "«O die ihr glaubt! Fürchtet Allah und seid mit den Wahrhaftigen»."),
"virtues_096": ("Mit wem gebietet der Koran dem Propheten ﷺ in Al-Kahf geduldig auszuharren?", ["Mit denen, die ihren Herrn morgens und abends anrufen und Sein Angesicht begehren", "Mit den Stammesführern", "Mit den reichen Kaufleuten", "Mit den Dichtern"], "«Und halte dich geduldig zu denen, die ihren Herrn morgens und abends anrufen und Sein Angesicht begehren; und deine Augen sollen nicht über sie hinwegsehen»."),
"virtues_097": ("Worin gebietet der Koran einander zu helfen, und worin verbietet er es?", ["In Frömmigkeit und Gutem zu helfen, nicht in Sünde und Übertretung", "In allem zu helfen", "Niemandem zu helfen", "Nur in der Familie zu helfen"], "«Und helft einander zur Güte und Gottesfurcht, aber helft einander nicht zur Sünde und Übertretung»."),
"virtues_098": ("Was gebietet der Koran bezüglich des geschlossenen Bundes und der bekräftigten Eide?", ["Den Bund zu erfüllen und Eide nach ihrer Bekräftigung nicht zu brechen", "Sie neu zu verhandeln", "Sie zu vergessen", "Sie zu verbergen"], "«Und haltet den Bund Allahs ein, wenn ihr ihn geschlossen habt, und brecht nicht die Eide nach ihrer Bekräftigung»."),
"virtues_099": ("Wann ist laut einem von al-Bukhari überlieferten Hadith der Glaube eines Menschen vollständig?", ["Wenn er für seinen Bruder liebt, was er für sich selbst liebt", "Wenn er das ganze Jahr fastet", "Wenn er all sein Gut hergibt", "Wenn er nach Mekka reist"], "«Keiner von euch glaubt wahrhaft, bis er für seinen Bruder liebt, was er für sich selbst liebt»."),
"virtues_100": ("In welchen Fällen sieht der Koran Gutes in vertraulichen Gesprächen?", ["Wenn zu Almosen, zu Gutem oder zur Aussöhnung zwischen den Menschen aufgerufen wird", "Beim Besprechen von Geschäften", "Beim Planen einer Reise", "Beim Weitergeben von Nachrichten"], "«Es ist nichts Gutes in vielen ihrer vertraulichen Gespräche, außer bei dem, der zu Almosen, zu Gutem oder zur Aussöhnung zwischen den Menschen aufruft»."),
}
